function inferTechnicalType(i){if(i?.technicalType&&TECH_LIBRARY[i.technicalType])return i.technicalType;let n=i?.name||'';return Object.entries(TECH_LIBRARY).find(([,x])=>x.match.test(n))?.[0]||''}
function sourceOf(i,k){return i?.dataSources?.[k]||'unknown'}
function scientificDataQuality(){let total=state.items.reduce((a,x)=>a+(+x.grams||0),0);if(!total)return {score:0,label:'—',details:[]};let weighted=0,details=[];const fields=['water','solids','pac','pod','sugars'];state.items.forEach(x=>{let i=ing(x.ingredientId);if(!i||!x.grams)return;let present=fields.filter(k=>i[k]!=null).length/fields.length;let sources=fields.filter(k=>sourceOf(i,k)==='declared').length/fields.length;let sugar=i.sugars>0?Math.min(1,sugarDetail(i).known/i.sugars):1;let q=.55*present+.25*sources+.20*sugar;weighted+=x.grams*q;if(q<.65)details.push(i.name)});let score=Math.round(weighted/total*100);return {score,label:score>=85?'Alta':score>=60?'Media':'Limitata',details:[...new Set(details)]}}

