let dbSyncTimer=null, dbReady=false, dbAuthoritative=false;
function canonicalState(){return {ingredients:ingredientDB.map(i=>({...i})),recipes:allRecipes().map(r=>({...r})),profiles:clone(profiles),feedbacks:clone(feedbacks())}}
async function syncDatabase(){if(!dbReady)return;try{let r=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({state:canonicalState()})});if(!r.ok)throw new Error('sync');setDbStatus('PostgreSQL · sincronizzato','ok')}catch(e){setDbStatus('Database non raggiungibile','bad')}}
function scheduleDbSync(){clearTimeout(dbSyncTimer);dbSyncTimer=setTimeout(syncDatabase,250)}
const setJSON=(k,v)=>{localStorage.setItem(k,JSON.stringify(v));scheduleDbSync()};
function setDbStatus(text,kind=''){let el=document.getElementById('dbStatus');if(el){el.textContent=text;el.className='dbStatus '+kind}}
function installDbState(st){
 dbAuthoritative=true;
 ingredientDB=Array.isArray(st.ingredients)?st.ingredients:[];
 profiles=normalizeProfiles(st.profiles&&Object.keys(st.profiles).length?st.profiles:clone(DEFAULT_PROFILES)); draftProfiles=clone(profiles);
 localStorage.setItem(KEYS.ingredients,JSON.stringify(ingredientDB));
 localStorage.setItem(KEYS.recipes,JSON.stringify(Array.isArray(st.recipes)?st.recipes:[]));
 localStorage.setItem(KEYS.recipeMeta,JSON.stringify(Object.fromEntries(D.recipes.map(r=>[r.id,{deleted:true}]))));
 localStorage.setItem(KEYS.profiles,JSON.stringify(profiles));
 localStorage.setItem(KEYS.feedbacks,JSON.stringify(st.feedbacks||{}));
}
async function hydrateFromDatabase(){setDbStatus('Connessione PostgreSQL…');try{let r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw new Error('api');let j=await r.json();dbReady=true;if(!j.empty&&j.state){installDbState(j.state);setDbStatus(`PostgreSQL · ${j.counts.ingredients} ingredienti · ${j.counts.recipes} ricette`,'ok');return true}setDbStatus('PostgreSQL vuoto · migrazione iniziale','ok');return false}catch(e){dbReady=false;setDbStatus('Database non raggiungibile','bad');return false}}

let profiles=getJSON(KEYS.profiles,clone(DEFAULT_PROFILES));
function normalizeProfiles(ps){Object.values(ps).forEach(p=>{p.display=p.display||{};p.evaluate=p.evaluate||{};Object.keys(p.ranges).forEach(k=>{if(p.display[k]==null)p.display[k]=!(p.label==='Granita'&&['fat','msnf'].includes(k));if(p.evaluate[k]==null)p.evaluate[k]=p.display[k]});if(p.display.pacWater==null)p.display.pacWater=true;if(p.evaluate.pacWater==null)p.evaluate.pacWater=false;p.source=p.source||'Standard IceC · riferimento professionale + personalizzazione utente'});return ps}
