function feedbackHtml(id,editable=false){let logs=(feedbacks()[id]||[]).slice().reverse();if(!logs.length)return '<div class="empty">Nessuna nota post-produzione registrata.</div>';return logs.map(x=>`<div class="historyItem"><div class="historyHead"><small>${new Date(x.date).toLocaleString('it-IT')}</small>${editable?`<button class="danger mini" onclick="deleteFeedback('${id}','${x.id}')">Elimina</button>`:''}</div><div>${x.note}</div><details><summary>Ricetta usata per questa nota</summary><button class="mini" onclick="event.preventDefault();event.stopPropagation();compareSnapshot('${id}','${x.id}')">Confronta con attuale</button><div class="snapshot"><b>${snapshotSummary(x.snapshot)}</b>${(x.snapshot.items||[]).map(it=>`<span>${ing(it.ingredientId)?.name||'Ingrediente non disponibile'} <b>${fmt(it.grams,1)} g</b></span>`).join('')}</div></details></div>`).join('')}
window.deleteFeedback=(recipeId,noteId)=>{if(!confirm('Eliminare questa nota post-produzione?'))return;let all=feedbacks();all[recipeId]=(all[recipeId]||[]).filter(x=>x.id!==noteId);setJSON(KEYS.feedbacks,all);editRecipe(recipeId);if(state.loadedId===recipeId)renderFeedbackHistory()}
window.editRecipe=id=>{let r=allRecipes().find(x=>x.id===id);if(!r)return;openModal(`<h2>Modifica ricetta</h2><form id="recipeForm"><label>Nome<input name="name" required value="${r.name}"></label><label>Categoria<select name="category">${profileOptions(r.category,true)}</select></label><label>Note generali<textarea name="notes" placeholder="Indicazioni stabili della ricetta">${r.notes||''}</textarea></label><div class="modalActions"><button type="button" class="danger" id="deleteRecipe">Elimina ricetta</button><button type="button" id="balanceRecipe">Apri nel bilanciatore</button><button class="primary" type="submit">Salva modifiche</button></div></form><div class="feedbackEditor"><h3>Note post-produzione</h3><p>Registra qui il feedback dopo l'assaggio. Ogni nota conserva una fotografia della ricetta usata in quel momento.</p><textarea id="newFeedback" placeholder="Es. dopo 24 h a −18 °C risulta leggermente duro..."></textarea><button id="addFeedback" class="primary">Aggiungi nota</button><div class="history">${feedbackHtml(id,true)}</div></div>`);$('#recipeForm').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),users=userRecipes(),u=users.find(x=>x.id===id);if(u){u.name=fd.get('name').trim();u.category=fd.get('category');u.notes=fd.get('notes').trim();setJSON(KEYS.recipes,users)}else{let m=recipeMeta();m[id]={...(m[id]||{}),name:fd.get('name').trim(),category:fd.get('category'),notes:fd.get('notes').trim()};setJSON(KEYS.recipeMeta,m)}closeModal();fillRecipeSelect();renderRecipes();if(state.loadedId===id)loadRecipe(id)};$('#addFeedback').onclick=()=>{let note=$('#newFeedback').value.trim();if(!note){alert('Inserisci una nota.');return}let current=allRecipes().find(x=>x.id===id),all=feedbacks();(all[id]||(all[id]=[])).push({id:'f'+Date.now(),date:new Date().toISOString(),note,snapshot:recipeSnapshot(current)});setJSON(KEYS.feedbacks,all);editRecipe(id);if(state.loadedId===id)renderFeedbackHistory()};$('#balanceRecipe').onclick=()=>{closeModal();openR(id)};$('#deleteRecipe').onclick=()=>{if(!confirm(`Eliminare la ricetta "${r.name}"? L'operazione non può essere annullata.`))return;let users=userRecipes();if(users.some(x=>x.id===id)){setJSON(KEYS.recipes,users.filter(x=>x.id!==id))}else{let m=recipeMeta();m[id]={...(m[id]||{}),deleted:true};setJSON(KEYS.recipeMeta,m)}let fb=feedbacks();delete fb[id];setJSON(KEYS.feedbacks,fb);if(state.loadedId===id)newRecipe();closeModal();fillRecipeSelect();renderRecipes()}};
function renderFeedbackHistory(){let box=$('#feedbackHistory');if(!box)return;box.innerHTML=state.loadedId?feedbackHtml(state.loadedId,false):'<div class="empty">Carica una ricetta per vedere eventuali note post-produzione.</div>'}

function buildPrintDocument(r,mode='production'){let x=nutritionForItems(r.items||[]),m=x.m,total=x.total,alls=recipeAllergens(r.items||[]),p=profiles[r.category]||{};let rows=(r.items||[]).map(it=>{let ii=ing(it.ingredientId);return '<tr><td>'+ (ii?.name||'Ingrediente') +'</td><td>'+fmt(it.grams,1)+' g</td><td>'+fmt(total?it.grams/total*100:0,1)+'%</td></tr>'}).join('');let technical=mode==='technical'?'<h2>Parametri tecnici</h2><div class="printGrid"><span>Zuccheri <b>'+fmt(m.sugars)+'%</b></span><span>Grassi <b>'+fmt(m.fat)+'%</b></span><span>Proteine <b>'+fmt(m.protein)+'%</b></span><span>Solidi <b>'+fmt(m.solids)+'%</b></span><span>Acqua <b>'+fmt(m.water)+'%</b></span><span>PAC <b>'+fmt(m.pac)+'</b></span><span>POD <b>'+fmt(m.pod)+'</b></span></div><h2>Valori nutrizionali stimati / 100 g</h2><div class="printGrid"><span>Energia <b>'+fmt(m.kcal,0)+' kcal</b></span><span>Carboidrati <b>'+fmt(m.carbs)+' g</b></span><span>di cui zuccheri <b>'+fmt(m.sugars)+' g</b></span><span>Grassi <b>'+fmt(m.fat)+' g</b></span><span>Proteine <b>'+fmt(m.protein)+' g</b></span><span>Fibre <b>'+fmt(m.fiber)+' g</b></span><span>Sale <b>'+fmt(m.salt,2)+' g</b></span></div><h2>Allergeni</h2><p>'+(alls.length?alls.join(', '):'Nessun allergene registrato negli ingredienti. Verificare sempre le etichette originali.')+'</p>':'';return '<!doctype html><html><head><meta charset="utf-8"><title>'+r.name+'</title><style>body{font-family:Arial,sans-serif;color:#17324d;margin:32px}h1{margin-bottom:4px}small{color:#668198}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{padding:8px;border-bottom:1px solid #d7eaf5;text-align:left}th:nth-child(n+2),td:nth-child(n+2){text-align:right}.printGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.printGrid span{padding:9px;background:#f4fbff;border-radius:8px}footer{margin-top:30px;font-size:10px;color:#668198}@media print{button{display:none}}</style></head><body><h1>'+r.name+'</h1><small>'+(p.label||'Non classificata')+' · '+fmt(total,0)+' g · IceC Lab v0.7.0</small><table><thead><tr><th>Ingrediente</th><th>Quantità</th><th>%</th></tr></thead><tbody>'+rows+'</tbody></table>'+technical+(r.notes?'<h2>Note ricetta</h2><p>'+r.notes+'</p>':'')+'<footer>Documento generato da IceC Lab. Valori nutrizionali e allergeni dipendono dalla completezza dei dati ingredienti e non sostituiscono verifiche normative o di laboratorio.</footer><script>window.onload=()=>window.print()<\/script></body></html>'}
function printRecipeObject(r,mode){let w=window.open('','_blank');if(!w)return alert('Consenti i popup per stampare la scheda.');w.document.write(buildPrintDocument(r,mode));w.document.close()}
window.printSavedRecipe=(id,mode='production')=>{let r=allRecipes().find(x=>x.id===id);if(r)printRecipeObject(r,mode)};
function currentRecipeForPrint(){return {id:state.loadedId||'draft',name:state.loadedName||'Nuova ricetta',category:state.profile,items:state.items.map(x=>({...x})),notes:state.loadedId?(allRecipes().find(x=>x.id===state.loadedId)?.notes||''):''}}
window.compareSnapshot=(rid,nid)=>{let r=allRecipes().find(x=>x.id===rid),n=(feedbacks()[rid]||[]).find(x=>x.id===nid);if(!r||!n)return;let a=nutritionForItems(r.items),b=nutritionForItems(n.snapshot.items||[]),keys=[['sugars','Zuccheri %'],['fat','Grassi %'],['protein','Proteine %'],['solids','Solidi %'],['water','Acqua %'],['pac','PAC'],['pod','POD']],rows=keys.map(([k,l])=>'<tr><td>'+l+'</td><td>'+fmt(b.m[k])+'</td><td>'+fmt(a.m[k])+'</td><td>'+((a.m[k]-b.m[k])>=0?'+':'')+fmt(a.m[k]-b.m[k])+'</td></tr>').join('');let oldMap=new Map((n.snapshot.items||[]).map(x=>[x.ingredientId,+x.grams||0])),newMap=new Map((r.items||[]).map(x=>[x.ingredientId,+x.grams||0])),ids=[...new Set([...oldMap.keys(),...newMap.keys()])],changes=ids.map(id=>({name:ing(id)?.name||'Ingrediente',d:(newMap.get(id)||0)-(oldMap.get(id)||0)})).filter(x=>Math.abs(x.d)>.05).map(x=>'<li>'+x.name+': '+(x.d>0?'+':'')+fmt(x.d,1)+' g</li>').join('');openModal('<h2>Confronto formulazioni</h2><p>Snapshot della nota del '+new Date(n.date).toLocaleString('it-IT')+' rispetto alla ricetta attuale.</p><table class="compareTable"><tr><th>Parametro</th><th>Snapshot</th><th>Attuale</th><th>Δ</th></tr>'+rows+'</table><h3>Variazioni ingredienti</h3>'+(changes?'<ul>'+changes+'</ul>':'<div class="empty">Nessuna variazione di grammatura.</div>'))};
function renderProfiles(){let labels={sugars:'Zuccheri %',fat:'Grassi %',msnf:'MSNF %',solids:'Solidi totali %',pac:'PAC',pod:'POD'};$('#profileEditor').innerHTML=Object.entries(draftProfiles).map(([id,p])=>`<div class="profilebox"><h3>${p.label}</h3><small>${p.source||''}</small><div class="rangegrid"><b>Parametro</b><b>Min</b><b>Max</b><b>Visibile</b><b>Valutato</b>${Object.entries(p.ranges).filter(([k])=>labels[k]).map(([k,r])=>`<span>${labels[k]}</span><input value="${r[0]}" type="number" step=".1" onchange="draftProfiles['${id}'].ranges['${k}'][0]=+this.value;markProfileDirty()"><input value="${r[1]}" type="number" step=".1" onchange="draftProfiles['${id}'].ranges['${k}'][1]=+this.value;markProfileDirty()"><input class="toggle" type="checkbox" ${p.display[k]!==false?'checked':''} onchange="draftProfiles['${id}'].display['${k}']=this.checked;markProfileDirty()"><input class="toggle" type="checkbox" ${p.evaluate[k]!==false?'checked':''} onchange="draftProfiles['${id}'].evaluate['${k}']=this.checked;markProfileDirty()">`).join('')}</div></div>`).join('')}
window.markProfileDirty=()=>{$('#profileSaveState').textContent='Modifiche non salvate';$('#profileSaveState').className='saveState dirty'};
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.add('open')}function closeModal(){$('#modal').classList.remove('open')}
$('#modalClose').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};$('#newIngredient').onclick=()=>ingredientModal();$('#addRow').onclick=()=>{state.items.push({ingredientId:'',grams:0});markRecipeDirty();renderFormula()};$('#newRecipe').onclick=newRecipe;$('#recipeLoad').onchange=e=>e.target.value?loadRecipe(e.target.value):newRecipe();$('#profile').onchange=e=>{state.profile=e.target.value;markRecipeDirty();renderMetrics()};$('#service').onchange=e=>{state.service=e.target.value;if(e.target.value==='home'){state.temp=-18;$('#temp').value=-18}else if(e.target.value==='display'){state.temp=-13;$('#temp').value=-13}renderMetrics()};$('#temp').onchange=e=>{state.temp=+e.target.value;state.service='custom';$('#service').value='custom';renderMetrics()};
function scaleTo(target){let{total}=calc();if(!total||target<=0)return;markRecipeDirty();let f=target/total;state.items.forEach(x=>{let i=ing(x.ingredientId),s=i&&(/neutro|stabil|diglicer|sale/i.test(i.name));x.grams=Math.round(x.grams*f*(s?10:1))/(s?10:1)});renderFormula()}$('#scaleBtn').onclick=()=>scaleTo(+$('#totalTarget').value);$('#plus10').onclick=()=>scaleTo(calc().total+10);$('#minus10').onclick=()=>scaleTo(Math.max(10,calc().total-10));function recipeNameExists(name,excludeId=null){return allRecipes().some(r=>r.id!==excludeId&&r.name.trim().toLowerCase()===name.trim().toLowerCase())}
function currentRecipePayload(name,id){return {id,name,category:state.profile,items:state.items.filter(x=>x.ingredientId).map(x=>({...x})),notes:'',updatedAt:new Date().toISOString()}}
function saveExistingRecipe(){if(!state.loadedId)return saveAsRecipe();let r=allRecipes().find(x=>x.id===state.loadedId);if(!r)return saveAsRecipe();let users=userRecipes(),u=users.find(x=>x.id===state.loadedId);if(u){u.category=state.profile;u.items=state.items.filter(x=>x.ingredientId).map(x=>({...x}));u.updatedAt=new Date().toISOString();setJSON(KEYS.recipes,users)}else{let meta=recipeMeta();meta[state.loadedId]={...(meta[state.loadedId]||{}),category:state.profile,itemsOverride:state.items.filter(x=>x.ingredientId).map(x=>({...x})),updatedAt:new Date().toISOString()};setJSON(KEYS.recipeMeta,meta)}state.dirty=false;fillRecipeSelect();renderRecipes();renderSaveActions();renderFormulaIdentity();alert('Modifiche salvate.')}
function saveAsRecipe(){let suggested=state.loadedId?state.loadedName+' copia':'';let name=prompt(state.loadedId?'Nome della nuova ricetta:':'Nome della ricetta:',suggested);if(!name)return;name=name.trim();if(!name)return;if(recipeNameExists(name)){alert(`Esiste già una ricetta chiamata "${name}". Scegli un nome diverso.`);return}let rs=userRecipes(),id='u'+Date.now();rs.push({...currentRecipePayload(name,id),createdAt:new Date().toISOString()});setJSON(KEYS.recipes,rs);state.loadedId=id;state.loadedName=name;state.dirty=false;$('#loadedName').textContent=name;fillRecipeSelect();$('#recipeLoad').value=id;renderRecipes();renderFeedbackHistory();renderSaveActions();alert('Nuova ricetta salvata.')}
function renderSaveActions(){if(!$('#saveRecipe'))return;$('#saveRecipe').textContent=state.loadedId?'Salva modifiche':'Salva ricetta…';$('#saveAsRecipe').style.display=state.loadedId?'inline-flex':'none';$('#saveHint').textContent=state.loadedId?`Stai modificando “${state.loadedName}”. Salva le modifiche oppure crea una copia indipendente.`:'Salva la formula nel Ricettario quando hai terminato il bilanciamento.'}
$('#saveRecipe').onclick=saveExistingRecipe;$('#saveAsRecipe').onclick=saveAsRecipe;
$('#printProduction').onclick=()=>printRecipeObject(currentRecipeForPrint(),'production');$('#printTechnical').onclick=()=>printRecipeObject(currentRecipeForPrint(),'technical');$('#batchWeight').oninput=renderMetrics;$('#portionWeight').oninput=renderMetrics;
$('#baseMode').onclick=()=>{state.advanced=false;$('#baseMode').classList.add('active');$('#advMode').classList.remove('active');renderMetrics()};$('#advMode').onclick=()=>{state.advanced=true;$('#advMode').classList.add('active');$('#baseMode').classList.remove('active');renderMetrics()};
$('#saveProfiles').onclick=()=>{profiles=normalizeProfiles(clone(draftProfiles));setJSON(KEYS.profiles,profiles);$('#profileSaveState').textContent='Profili salvati';$('#profileSaveState').className='saveState saved';fillRecipeSelect();renderMetrics();renderRecipes()};$('#resetProfiles').onclick=()=>{if(!confirm('Ripristinare i range predefiniti?'))return;draftProfiles=normalizeProfiles(clone(DEFAULT_PROFILES));renderProfiles();markProfileDirty()};
function switchView(v){document.querySelectorAll('.nav,.view').forEach(x=>x.classList.remove('active'));document.querySelector(`.nav[data-view="${v}"]`).classList.add('active');$('#'+v).classList.add('active');let titles={balance:['Bilanciamento','Formula, controlla, scala e salva le tue ricette.'],ingredients:['Ingredienti','Il database tecnico delle tue materie prime.'],recipes:['Ricettario','Organizza e riapri le formule già collaudate.'],settings:['Profili & range','Personalizza i target tecnici per categoria.']};$('#pageTitle').textContent=titles[v][0];$('#pageSub').textContent=titles[v][1]}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#checkIntegrity').onclick=checkIntegrity;$('#exportData').onclick=exportData;$('#importData').onchange=e=>{importDataFile(e.target.files[0]);e.target.value=''};$('#ingSearch').oninput=e=>renderIngredients(e.target.value);$('#recipeSearch').oninput=e=>{recipeQuery=e.target.value;renderRecipes()};

async function checkIntegrity(){const el=$('#integrityResult');el.textContent='Verifica in corso…';try{const r=await fetch('/api/integrity',{cache:'no-store'});const j=await r.json();if(!r.ok)throw new Error(j.error||'Errore');el.className='integrityResult '+(j.ok?'integrityOk':'integrityBad');el.innerHTML=`<b>${j.ok?'Integrità OK':'Attenzione'}</b> · ${j.counts.ingredients} ingredienti · ${j.counts.recipes} ricette · ${j.counts.profiles} profili · ${j.counts.notes} note${j.issues.length?'<br>'+j.issues.join('<br>'):''}`;}catch(e){el.className='integrityResult integrityBad';el.textContent='Verifica non riuscita: '+e.message}}
async function exportData(){try{const r=await fetch('/api/export',{cache:'no-store'});if(!r.ok)throw new Error('Export non riuscito');const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`icec-lab-export-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert(e.message)}}
async function importDataFile(file){if(!file)return;let parsed;try{parsed=JSON.parse(await file.text())}catch{return alert('Il file JSON non è valido.')}const st=parsed?.state||parsed;if(!st||!Array.isArray(st.ingredients)||!Array.isArray(st.recipes)||!st.profiles)return alert('Il file non sembra un export IceC valido.');if(!confirm(`Ripristinare questo backup?\\n\\n${st.ingredients.length} ingredienti\\n${st.recipes.length} ricette\\n\\nI dati attuali verranno sostituiti.`))return;try{const r=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({state:st})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Ripristino fallito');await hydrateFromDatabase();fillRecipeSelect();renderIngredients();renderRecipes();renderProfiles();newRecipe();await checkIntegrity();alert('Ripristino completato.')}catch(e){alert('Ripristino non riuscito: '+e.message)}}

async function bootIceC(){
 const hadDb=await hydrateFromDatabase();
 if(!hadDb){
   profiles=normalizeProfiles(getJSON(KEYS.profiles,clone(DEFAULT_PROFILES)));draftProfiles=clone(profiles);
   ingredientDB=getJSON(KEYS.ingredients,null)||D.ingredients.map(i=>({...i,_legacy:true}));
 }
 fillRecipeSelect();renderIngredients();renderRecipes();renderProfiles();newRecipe();
 if(!hadDb&&dbReady){
   await syncDatabase();
   const verify=await fetch('/api/state',{cache:'no-store'}).then(r=>r.json()).catch(()=>null);
   if(verify?.state){installDbState(verify.state);fillRecipeSelect();renderIngredients();renderRecipes();renderProfiles();newRecipe();setDbStatus(`Migrazione completata · ${verify.counts.ingredients} ingredienti · ${verify.counts.recipes} ricette`,'ok')}
 }
}
bootIceC();
